package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business/orders")
public class OrderController {
 private final JdbcTemplate db;private final AccessService access;
 public OrderController(JdbcTemplate db,AccessService access){this.db=db;this.access=access;}
 public Map<String,Object> readable(Actor a,long id){var order=access.one("select o.*,n.area_id,n.code node_code,u.username assignee_name from work_order o join monitoring_node n on n.id=o.node_id left join sys_user u on u.id=o.assignee_id where o.id=?",id);access.area(a,((Number)order.get("area_id")).longValue());if(!a.manager()&&!Objects.equals(order.get("assignee_id"),a.id())&&db.queryForObject("select count(*) from order_participant where order_id=? and user_id=?",Integer.class,id,a.id())==0)deny();order.put("participant_ids",db.queryForList("select user_id from order_participant where order_id=? order by user_id",Long.class,id));var names=db.queryForList("select u.username from order_participant p join sys_user u on u.id=p.user_id where p.order_id=? order by u.id",String.class,id);if(!names.isEmpty())order.put("assignee_name",String.join("、",names));return order;}
 @GetMapping public ApiResponse<?> list(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);String sql="select o.*,n.code node_code,n.area_id,u.username assignee_name from work_order o join monitoring_node n on n.id=o.node_id left join sys_user u on u.id=o.assignee_id ";return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList(sql+"order by o.id desc limit 500"):a.manager()?db.queryForList(sql+"join user_area ua on ua.area_id=n.area_id where ua.user_id=? order by o.id desc limit 500",a.id()):db.queryForList(sql+"join user_area ua on ua.area_id=n.area_id where ua.user_id=? and (o.assignee_id=? or exists(select 1 from order_participant op where op.order_id=o.id and op.user_id=?)) order by o.id desc limit 500",a.id(),a.id(),a.id()));}
 @GetMapping("/{id}") public ApiResponse<?> detail(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);var o=readable(a,id);o.put("events",db.queryForList("select e.*,u.username from order_event e join sys_user u on u.id=e.actor_id where e.order_id=? order by e.id",id));o.put("attachments",db.queryForList("select id,original_name,content_type,created_at from attachment where order_id=?",id));return ApiResponse.ok(o);}
 @PostMapping @Transactional public ApiResponse<?> create(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);long node=number(b,"nodeId");access.node(a,node);String title=text(b,"title",200),priority=Objects.toString(b.get("priority"),"MEDIUM");if(!Set.of("LOW","MEDIUM","HIGH").contains(priority))bad("优先级无效");Long alarmId=b.get("alarmId")==null?null:number(b,"alarmId");if(alarmId!=null){var alarm=access.one("select * from alarm where id=?",alarmId);if(((Number)alarm.get("node_id")).longValue()!=node)bad("告警与节点不一致");}
 long id=access.insert("insert into work_order(node_id,alarm_id,title,priority,creator_id,description) values(?,?,?,?,?,?)",node,alarmId,title,priority,a.id(),Objects.toString(b.get("description"),""));event(a,id,"CREATE","创建工单");return ApiResponse.ok(Map.of("id",id));}
 @PostMapping("/{id}/assign") @Transactional public ApiResponse<?> assign(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);db.queryForList("select id from work_order where id=? for update",id);var o=readable(a,id);if(Set.of("COMPLETED","CANCELLED","REVIEW").contains(o.get("status")))bad("当前状态不能派发");long user=number(b,"assigneeId");var target=access.one("select * from sys_user where id=? and enabled=true",user);if(!target.get("role_code").equals("INSPECTOR"))bad("请选择启用的巡检员");if(db.queryForObject("select count(*) from user_area where user_id=? and area_id=?",Integer.class,user,o.get("area_id"))==0)bad("执行人未分配该区域");var participants=new java.util.LinkedHashSet<Long>();if(b.get("participantIds") instanceof java.util.List<?> ids)for(Object value:ids)participants.add(Long.parseLong(value.toString()));else participants.add(user);if(participants.isEmpty()||participants.size()>2||!participants.contains(user))bad("请选择1至2位执行人");for(long participant:participants){var candidate=access.one("select * from sys_user where id=? and enabled=true",participant);if(!candidate.get("role_code").equals("INSPECTOR")||db.queryForObject("select count(*) from user_area where user_id=? and area_id=?",Integer.class,participant,o.get("area_id"))==0)bad("执行人未授权该区域");}String priority=text(b,"priority",20);if(!Set.of("LOW","MEDIUM","HIGH").contains(priority))bad("优先级无效");Timestamp due=null;if(b.get("dueAt")!=null&&!b.get("dueAt").toString().isBlank()){try{due=Timestamp.from(Instant.parse(b.get("dueAt").toString()));}catch(Exception e){bad("截止时间格式不正确");}if(due.toInstant().isBefore(Instant.now()))bad("截止时间必须在未来");}db.update("update work_order set assignee_id=?,priority=?,due_at=?,status='ASSIGNED',updated_at=CURRENT_TIMESTAMP where id=?",user,priority,due,id);db.update("delete from order_participant where order_id=?",id);for(long participant:participants){db.update("insert into order_participant(order_id,user_id) values(?,?)",id,participant);access.notify(participant,"新巡检工单",o.get("title").toString(),"ORDER",id);}event(a,id,"ASSIGN",text(b,"note",2000));return ApiResponse.ok(null);}
 @PostMapping("/{id}/action") @Transactional public ApiResponse<?> action(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);var o=readable(a,id);db.queryForList("select id from work_order where id=? for update",id);o=readable(a,id);String action=text(b,"action",30),status=o.get("status").toString(),next;String note=Objects.toString(b.get("note"),"").trim();if(note.length()>2000)bad("备注过长");
 switch(action){
 case "accept": if(!status.equals("ASSIGNED"))bad("工单不是待接单状态");owner(a,o);next="ACCEPTED";break;
 case "start": if(!status.equals("ACCEPTED"))bad("请先接单");owner(a,o);next="PROCESSING";break;
 case "submit": if(!status.equals("PROCESSING"))bad("工单不在处理中");owner(a,o);String result=text(b,"result",4000);String readings=Objects.toString(b.get("readings"),"");if(readings.length()>2000)bad("读数过长");db.update("update work_order set result_text=?,readings=? where id=?",result,readings,id);next="REVIEW";break;
 case "approve": access.manager(a);if(!status.equals("REVIEW"))bad("工单不在待复核状态");if(Objects.equals(o.get("assignee_id"),a.id()))bad("不能复核自己执行的工单");next="COMPLETED";break;
 case "reject": access.manager(a);if(!status.equals("REVIEW"))bad("工单不在待复核状态");if(note.isBlank())bad("请填写退回原因");next="PROCESSING";break;
 case "cancel": access.manager(a);if(Set.of("COMPLETED","CANCELLED").contains(status))bad("工单已结束");if(note.isBlank())bad("请填写取消原因");next="CANCELLED";break;
 default: bad("未知工单操作");return ApiResponse.ok(null);
 }
 db.update("update work_order set status=?,updated_at=CURRENT_TIMESTAMP where id=?",next,id);event(a,id,action.toUpperCase(),note);if(o.get("assignee_id")!=null&&(action.equals("reject")||action.equals("approve")))access.notify(((Number)o.get("assignee_id")).longValue(),"工单复核结果",next+" "+note,"ORDER",id);if(action.equals("submit"))db.update("insert into notification(user_id,title,content,object_type,object_id) select distinct u.id,'工单待复核',?,'ORDER',? from sys_user u left join user_area ua on ua.user_id=u.id where u.enabled=true and (u.role_code='ADMIN' or (u.role_code='MANAGER' and ua.area_id=?))",o.get("title"),id,o.get("area_id"));return ApiResponse.ok(null);}
 @PostMapping("/batch-assign") @Transactional public ApiResponse<?> batchAssign(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);if(!(b.get("orderIds") instanceof List<?>))bad("请选择工单");var ids=(List<?>)b.get("orderIds");if(ids.isEmpty()||ids.size()>100)bad("每次最多指派100单");var sorted=new TreeSet<Long>();for(Object id:ids)sorted.add(Long.parseLong(id.toString()));for(long id:sorted)assign(jwt,id,b);return ApiResponse.ok(null);}
 private void owner(Actor a,Map<String,Object>o){if(!Objects.equals(o.get("assignee_id"),a.id())&&db.queryForObject("select count(*) from order_participant where order_id=? and user_id=?",Integer.class,o.get("id"),a.id())==0)deny();}
 @PostMapping("/{id}/schedule") @Transactional public ApiResponse<?> schedule(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);db.queryForList("select id from work_order where id=? for update",id);var o=readable(a,id);if(Set.of("COMPLETED","CANCELLED").contains(o.get("status")))bad("已结束工单不能调整");String priority=text(b,"priority",20);if(!Set.of("LOW","MEDIUM","HIGH").contains(priority))bad("优先级无效");Timestamp due=null;if(b.get("dueAt")!=null&&!b.get("dueAt").toString().isBlank()){due=Timestamp.from(Instant.parse(b.get("dueAt").toString()));if(due.toInstant().isBefore(Instant.now()))bad("截止时间必须在未来");}db.update("update work_order set priority=?,due_at=?,updated_at=CURRENT_TIMESTAMP where id=?",priority,due,id);event(a,id,"UPDATE_SCHEDULE",text(b,"note",2000));return ApiResponse.ok(null);}
 private void event(Actor a,long id,String action,String note){db.update("insert into order_event(order_id,actor_id,action,note) values(?,?,?,?)",id,a.id(),action,note);access.audit(a,action,"ORDER",id,null,note);}
}
